/**
 * 🚲 Smooth Location Interpolation (Lerp)
 * Prevents pins from jumping visually when new coordinates arrive.
 */
function useSmoothLocation(lat?: number, lng?: number) {
  const [smoothLat, setSmoothLat] = useState<number | undefined>(lat);
  const [smoothLng, setSmoothLng] = useState<number | undefined>(lng);
  const requestRef = useRef<number>(undefined);
  const targetRef = useRef({ lat, lng });
  const animateRef = useRef<() => void>(undefined);

  useEffect(() => {
    targetRef.current = { lat, lng };
  }, [lat, lng]);

  const animate = useCallback(() => {
    if (targetRef.current.lat !== undefined && targetRef.current.lng !== undefined) {
      setSmoothLat((prev) => {
        if (prev === undefined) return targetRef.current.lat;
        const diff = targetRef.current.lat! - prev;
        if (Math.abs(diff) < 0.000001) return targetRef.current.lat!;
        return prev + diff * 0.1; // Lerp factor for ultra-smooth easing
      });
      setSmoothLng((prev) => {
        if (prev === undefined) return targetRef.current.lng;
        const diff = targetRef.current.lng! - prev;
        if (Math.abs(diff) < 0.000001) return targetRef.current.lng!;
        return prev + diff * 0.1;
      });
    }
    if (animateRef.current) {
      requestRef.current = requestAnimationFrame(animateRef.current);
    }
  }, []);

  useEffect(() => {
    animateRef.current = animate;
  });

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  return { lat: smoothLat, lng: smoothLng };
}

const LeafletMap = ({
  center,
  zoom = 13,
  onLocationSelect,
}: {
  center: { lat: number; lng: number };
  zoom?: number;
  onLocationSelect?: (lat: number, lng: number) => void;
}) => {
  const MapEvents = () => {
    useMapEvents({
      click(e) {
        if (onLocationSelect) {
          onLocationSelect(e.latlng.lat, e.latlng.lng);
        }
      },
    });
    return null;
  };

  const ChangeView = ({ coords }: { coords: { lat: number; lng: number } }) => {
    const map = useMap();
    useEffect(() => {
      map.setView([coords.lat, coords.lng], zoom);
    }, [coords, map]);
    return null;
  };

  return (
    <div className="w-full h-full min-h-[200px] rounded-xl overflow-hidden shadow-inner border border-outline-variant/10 relative z-0">
      <MapContainer
        center={[center.lat, center.lng]}
        zoom={zoom}
        style={{ height: "100%", width: "100%" }}
        scrollWheelZoom={true}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <Marker
          position={[center.lat, center.lng]}
          draggable={true}
          eventHandlers={{
            dragend: (e) => {
              const marker = e.target;
              const position = marker.getLatLng();
              if (onLocationSelect) {
                onLocationSelect(position.lat, position.lng);
              }
            },
          }}
        />
        <MapEvents />
        <ChangeView coords={center} />
      </MapContainer>
    </div>
  );
};

interface OSMPrediction {
  lat: string;
  lon: string;
  display_name: string;
  address: {
    city?: string;
    town?: string;
    village?: string;
    suburb?: string;
  };
}

const AddressAutocomplete = ({
  value,
  onChange,
  onSelect,
  placeholder = "Search address...",
}: {
  value: string;
  onChange: (val: string) => void;
  onSelect: (address: string, city: string, lat: number, lng: number) => void;
  placeholder?: string;
}) => {
  const [predictions, setPredictions] = useState<OSMPrediction[]>([]);
  const [isLocating, setIsLocating] = useState(false);

  useEffect(() => {
    const timeoutId = setTimeout(async () => {
      if (!value || value.length < 3) {
        setPredictions([]);
        return;
      }

      try {
        const query = `${value} Tembisa Midrand South Africa`;
        const response = await fetch(
          `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(
            query,
          )}&format=json&addressdetails=1&limit=5&countrycodes=za&email=aviwenotununu4@gmail.com`,
          {
            headers: {
              "Accept-Language": "en",
            },
          },
        );
        const data = await response.json();
        setPredictions((data as OSMPrediction[]) || []);
      } catch (error) {
        console.error("OSM Nominatim Error:", error);
      }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [value]);

  const useCurrentLocation = () => {
    if (!navigator.geolocation) {
      toast.error("Geolocation not supported");
      return;
    }

    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude, accuracy } = pos.coords;
        console.log(`Captured GPS: ${latitude}, ${longitude} (Precision: ${accuracy}m)`);
        
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&addressdetails=1`,
          );
          const data = await res.json();
          const { formattedAddress, city } = parseAndNormalizeZAAddress(data.display_name || "Current GPS Location");
          onSelect(formattedAddress, city, latitude, longitude);
          onChange(formattedAddress);
          toast.success("High-precision GPS captured!");
        } catch {
          onSelect("GPS Location", "Tembisa", latitude, longitude);
          onChange(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
        } finally {
          setIsLocating(false);
        }
      },
      () => {
        toast.error("Low precision or GPS denied. Please search manually.");
        setIsLocating(false);
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  const handleSelect = (prediction: OSMPrediction) => {
    const lat = parseFloat(prediction.lat);
    const lon = parseFloat(prediction.lon);
    const { formattedAddress, city } = parseAndNormalizeZAAddress(prediction.display_name);

    onChange(formattedAddress);
    setPredictions([]);
    onSelect(formattedAddress, city, lat, lon);
  };

  return (
    <div className="relative w-full">
      <div className="relative">
        <MapPin
          className="absolute left-4 top-1/2 -translate-y-1/2 text-primary/40"
          size={18}
        />
        <input
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className="w-full h-14 bg-surface-container-low border border-outline-variant/10 rounded-2xl pl-12 pr-14 focus:ring-2 focus:ring-primary/40 transition-all outline-none text-base"
        />
        <button
          onClick={useCurrentLocation}
          className="absolute right-4 top-1/2 -translate-y-1/2 p-2 hover:bg-primary/10 rounded-xl text-primary transition-all active:scale-95"
          title="Use current GPS"
          disabled={isLocating}
        >
          <Navigation size={20} className={isLocating ? "animate-pulse" : ""} />
        </button>
      </div>

      <AnimatePresence>
        {predictions.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="absolute z-50 w-full mt-2 bg-white dark:bg-zinc-900 border border-outline-variant/20 rounded-2xl shadow-2xl overflow-hidden"
          >
            {predictions.map((p, idx) => (
              <button
                key={`${p.place_id}-${idx}`}
                onClick={() => handleSelect(p)}
                className="w-full text-left p-4 hover:bg-primary/5 transition-colors border-b border-outline-variant/5 last:border-none group"
              >
                <p className="text-sm font-bold text-on-surface group-hover:text-primary transition-colors line-clamp-1">
                  {p.display_name.split(",")[0]}
                </p>
                <p className="text-[10px] text-on-surface-variant line-clamp-1">
                  {p.display_name}
                </p>
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

